1	/**
2	 * The screen a map builds itself on.
3	 *
4	 * The same canvas, the same panel and the same keyboard as every other map. What
5	 * is different is where the map comes from: it arrives claim by claim down one
6	 * request, with a reserved rectangle standing wherever the next one will go, and
7	 * every proposal the rules refused listed beside it.
8	 *
9	 * **There is no spinner here, and no moment where a blank screen turns into a
10	 * finished picture.** The growing *is* the loading state.
11	 *
12	 * **This screen does not ask for the map.** The press that opened it did
13	 * (`theRun.ts`), and this watches what that press started. It can be mounted,
14	 * unmounted and mounted again — which React's development mode does on purpose —
15	 * without a second generation being asked for, because there is no code here
16	 * that could ask for one.
17	 */
18	
19	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
20	import { outlineOf } from "../a11y/sentences";
21	import { AddAClaim } from "../components/AddAClaim";
22	import { type Command, CommandPalette } from "../components/CommandPalette";
23	import { DoneLine } from "../components/DoneLine";
24	import { Inspector } from "../components/Inspector";
25	import { MapFrame } from "../components/MapFrame";
26	import { Outline } from "../components/Outline";
27	import { ReceiptStrip } from "../components/ReceiptStrip";
28	import { RefusalStrip } from "../components/RefusalStrip";
29	import { ReplayBadge, replaySentence } from "../components/ReplayBadge";
30	import { ShortcutsSheet } from "../components/ShortcutsSheet";
31	import { VerdictCard } from "../components/VerdictCard";
32	import { MapCanvas } from "../graph/Canvas";
33	import type { MapKeys } from "../keyboard/useMapKeys";
34	import type { Selection } from "../world";
35	import { hasStopped } from "./growth";
36	import type { TheRun, WhereItHasGot } from "./theRun";
37	import type { Working } from "./transcript";
38	import { readTranscript } from "./transcript";
39	import "../components/generationDock.css";
40	
41	/**
42	 * Watch a run that is already going.
43	 *
44	 * `useSyncExternalStore` is React's own way of reading something that lives
45	 * outside React and changes on its own, and it is the right one here for a
46	 * reason that matters: subscribing and unsubscribing does nothing to the run.
47	 * A hook that *started* the generation would start two of them in development,
48	 * and *"never retry, a generation that ran twice would spend twice"* would be
49	 * broken on every machine where the app is developed.
50	 *
51	 * @param run The generation the press created.
52	 */
53	function useTheRun(run: TheRun): WhereItHasGot {
54	  return useSyncExternalStore(run.watch, run.now, run.now);
55	}
56	
57	/** What the screen needs. */
58	export interface GenerationScreenProps {
59	  /** The run, already asked for by the press that opened this screen. */
60	  readonly run: TheRun;
61	  /**
62	   * True when this copy has no model key, so the run is a recording being played
63	   * back. Known before the stream says anything, which is why the badge can be
64	   * on screen from the first frame — and why the offer to run it again can say
65	   * truthfully whether pressing it spends money.
66	   */
67	  readonly replaying: boolean;
68	  /** Ask for the same sentence again. A press, like the first one. */
69	  readonly onRunAgain: () => void;
70	  /** Let go of this run and go back. A press, and the only way off this screen. */
71	  readonly onLeave: () => void;
72	}
73	
74	/** A map building itself, and the panel beside it. */
75	export function GenerationScreen({ run, replaying, onRunAgain, onLeave }: GenerationScreenProps) {
76	  const { growth, saying } = useTheRun(run);
77	  const [selection, setSelection] = useState<Selection>(null);
78	  const [focused, setFocused] = useState<string | null>(null);
79	  const [overlay, setOverlay] = useState<"sheet" | "palette" | null>(null);
80	  const [dock, setDock] = useState<"panel" | "outline">("panel");
81	  const [openAt, setOpenAt] = useState<number | null>(null);
82	  const [status, setStatus] = useState(
83	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
84	  );
85	  const [working, setWorking] = useState<Working>({ state: "reading" });
86	
87	  const { generationId, phase } = growth;
88	  const finished = hasStopped(phase);
89	
90	  // The working of the run, read once the run has finished. It is asked for then
91	  // rather than as it goes, because the server writes it from the same pass that
92	  // writes the stream and a half-read one would be a second, staler copy.
93	  //
94	  // **A run that ended early has a working too**, and it is the one case where
95	  // reading it back matters most: it is the only record of how far the run got.
96	  useEffect(() => {
97	    if (generationId === null || !finished) {
98	      return;
99	    }
100	    let stillWanted = true;
101	    readTranscript(generationId).then(
102	      (read) => {
103	        if (stillWanted) {
104	          setWorking(read);
105	        }
106	      },
107	      // `readTranscript` answers rather than throws, for every failure it can
108	      // name. This is for the ones it cannot: a screen that waits for a promise
109	      // that will never settle says *Reading the working…* until the tab closes.
110	      () => {
111	        if (stillWanted) {
112	          setWorking({
113	            state: "gone",
114	            reason: "The working of this run could not be read, and nothing said why.",
115	          });
116	        }
117	      },
118	    );
119	    return () => {
120	      stillWanted = false;
121	    };
122	  }, [generationId, finished]);
123	
124	  const outline = useMemo(() => outlineOf(growth.world), [growth.world]);
125	
126	  // The keyboard follows the growing edge: a claim that has just arrived takes
127	  // focus, exactly as a claim a branch adds does. That is what keeps the newest
128	  // tile on the glass through a run that goes on for minutes — the canvas
129	  // already brings whatever the keyboard is on into view, so nothing here
130	  // re-frames the map and nothing re-lays it out. A tile that is already placed
131	  // stays exactly where it is; what moves is where the reader is looking.
132	  //
133	  // A claim that has just **arrived** takes focus, and nothing else does. The
134	  // count is what says one arrived: when the likelihoods land, the engine's own
135	  // world replaces the drawing and its claims come back in the map's order
136	  // rather than the order they were proposed in — which is not an arrival, and
137	  // moving the view for it would slide the map sideways at the very moment it
138	  // stopped changing.
139	  const howManyClaims = growth.world.claims.length;
140	  const seenSoFar = useRef(0);
141	  const lastArrived = useRef<string | null>(null);
142	  useEffect(() => {
143	    if (howManyClaims <= seenSoFar.current) {
144	      return;
145	    }
146	    seenSoFar.current = howManyClaims;
147	    const arrived = growth.world.claims[howManyClaims - 1]?.id ?? null;
148	    lastArrived.current = arrived;
149	    setFocused(arrived);
150	  }, [howManyClaims, growth.world.claims]);
151	
152	  // And it lets go the moment the run stops. Focus is also what the hover lens
153	  // reads, and a lens left on a claim the machine chose would dim the whole
154	  // finished map to fifteen per cent at exactly the moment the reader starts
155	  // reading it. If the reader has moved since, their focus is theirs and stays.
156	  useEffect(() => {
157	    if (!finished) {
158	      return;
159	    }
160	    setFocused((was) => (was === lastArrived.current ? null : was));
161	  }, [finished]);
162	
163	  const pick = useCallback((id: string) => {
164	    setFocused(id);
165	    setSelection({ kind: "claim", id });
166	  }, []);
167	
168	  // Nothing on this screen is bound to the map's own six operations yet, so the
169	  // keys that open them say so rather than doing nothing.
170	  /**
171	   * Every command this screen has, by name.
172	   *
173	   * **It is a screen's own list, not a copy of the stored map's.** A generated
174	   * map has no branches to open and none of the six things you can do to a
175	   * claim, so offering them here would be a palette full of commands that
176	   * explain why they cannot run. What it does have is the four ways around it
177	   * and the two things it can do, and each one is also a key or a control on
178	   * the screen — which is the palette's whole promise.
179	   *
180	   * Before this, ⌘K on this screen opened the shortcuts sheet: a key that
181	   * silently does something else is the one thing this product's keyboard is
182	   * not allowed to do.
183	   */
184	  const commands: Command[] = useMemo(
185	    () => [
186	      {
187	        name: "Read the map as a list",
188	        does: "The same as pressing O. Every claim, one sentence each, in the order they arrived.",
189	        run: () => {
190	          setDock("outline");
191	          setStatus("the map as a list");
192	        },
193	      },
194	      {
195	        name: "Read the panel beside the map",
196	        does: "The same as pressing O again. What this run refused, what it cost, and why.",
197	        run: () => {
198	          setDock("panel");
199	          setStatus("the panel beside the map");
200	        },
201	      },
202	      ...(generationId === null
203	        ? []
204	        : [
205	            {
206	              name: "Read the working of this run",
207	              does: "Every call it made, in order. The same as the control in the panel.",
208	              run: () => {
209	                setOpenAt(null);
210	                setDock("panel");
211	                setSelection({ kind: "generation", id: generationId });
212	              },
213	            },
214	          ]),
215	      {
216	        name: "Every key",
217	        does: "The sheet of every key on this map. The same as pressing ?.",
218	        run: () => setOverlay("sheet"),
219	      },
220	      {
221	        name: "Back to the launchpad",
222	        does: "Let this run go and start again. The same as the control at the top left.",
223	        run: onLeave,
224	      },
225	    ],
226	    [generationId, onLeave],
227	  );
228	
229	  const keys: MapKeys = useMemo(
230	    () => ({
231	      intervene: () => setStatus("a generated map takes edits through Add a claim, beside the map"),
232	      branch: () => setStatus("a branch is started on a stored map; this one is still being built"),
233	      flipWorlds: () => setStatus("there is nothing to flip to — no branch is open"),
234	      outline: () =>
235	        setDock((was) => {
236	          const next = was === "outline" ? "panel" : "outline";
237	          setStatus(next === "outline" ? "the map as a list" : "the panel beside the map");
238	          return next;
239	        }),
240	      panel: () => setStatus("the panel is beside the map"),
241	      palette: () => setOverlay("palette"),
242	    }),
243	    [],
244	  );
245	
246	  return (
247	    <MapFrame
248	      title={growth.world.title}
249	      onLeave={onLeave}
250	      onEveryKey={() => setOverlay("sheet")}
251	      where={
252	        <p className="map-bar__where">
253	          {/* Nothing sits over the map: the mark that says this run is a
254	              recording is a badge up here, and the sentence explaining it is in
255	              the line under the map with every other sentence about where this
256	              map came from. */}
257	          {replaying ? (
258	            <ReplayBadge
259	              recordingDate={growth.receipt?.recording_date ?? null}
260	              receiptMode={growth.receipt?.mode ?? null}
261	            />
262	          ) : null}
263	          {run.asked.target === null ? "Explore" : "Verify"}
264	          <span className="map-bar__side">
265	            {run.asked.target === null ? "what your sentence would cause" : run.asked.target}
266	          </span>
267	        </p>
268	      }
269	      map={
270	        <MapCanvas
271	          world={growth.world}
272	          selection={selection}
273	          onSelect={setSelection}
274	          focused={focused}
275	          onFocused={setFocused}
276	          mapKey={generationId ?? "a run that has not started"}
277	          keys={keys}
278	          onStatus={setStatus}
279	          onOverflow={() => setStatus("every claim is in the list beside the map")}
280	          arriving={!finished}
281	          reserved={growth.skeletons}
282	          // Framed once when the first rectangle is drawn, and once more when
283	          // the run stops — the one moment nothing on the map is moving and the
284	          // reader is about to start reading it.
285	          frameAgainOn={finished ? "the run stopped" : undefined}
286	        />
287	      }
288	      overlay={
289	        <>
290	          {overlay === "palette" ? (
291	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
292	          ) : null}
293	          {overlay === "sheet" ? (
294	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
295	          ) : null}
296	        </>
297	      }
298	      status={status}
299	      // Said out loud, and said once — and it says what just **changed** rather
300	      // than re-reading the whole run. Here the same facts are already drawn:
301	      // the claims on the canvas, the refusals in the panel, why the run
302	      // stopped under the map. Printing them again made the foot of the screen
303	      // three strips of prose saying the same thing twice.
304	      saying={saying}
305	      spokenOnly={true}
306	      panel={
307	        /* The map as a list, in place of the panel, exactly as it is on a
308	           stored map: press O for it, press O again for the panel. It grows as
309	           the map grows, in the same causal order, so a reader who never sees
310	           the canvas hears the map being built rather than a silence followed
311	           by a finished list. */
312	        dock === "outline" ? (
313	          <Outline items={outline} onPick={pick} focused={focused} />
314	        ) : (
315	          <>
316	            {/* The Verify door's answer, at the top, when a destination was named. */}
317	            {growth.verdict === null || run.asked.target === null ? null : (
318	              <VerdictCard
319	                verdict={growth.verdict}
320	                target={run.asked.target}
321	                world={growth.world}
322	                onSelect={pick}
323	              />
324	            )}
325	
326	            <RefusalStrip
327	              refusals={growth.refusals}
328	              finished={finished}
329	              openAt={openAt}
330	              onOpen={(at) => {
331	                setOpenAt(at);
332	                setSelection({ kind: "generation", id: generationId ?? "" });
333	              }}
334	            />
335	
336	            {growth.receipt === null ? null : <ReceiptStrip receipt={growth.receipt} />}
337	
338	            {/* **One way into the working that is always there.**
339	                The panel's view of the run used to be reachable only from a
340	                refusal row or from the receipt strip's link — so a run that
341	                refused nothing had one way in, and only at the end, and a run
342	                whose stream was cut had none at all. That last one is the worst
343	                of the three: the working is the only record of how far a cut
344	                run got, the screen fetches it for exactly that reason, and then
345	                offered the reader no way to read it. */}
346	            {generationId === null ? null : (
347	              <section className="generation-working" aria-label="The working of this run">
348	                <button
349	                  className="generation-working__open"
350	                  type="button"
351	                  onClick={() => {
352	                    setOpenAt(null);
353	                    setDock("panel");
354	                    setSelection({ kind: "generation", id: generationId });
355	                  }}
356	                >
357	                  Read the working of this run <span aria-hidden="true">→</span>
358	                </button>
359	              </section>
360	            )}
361	
362	            {finished && growth.world.baseId !== "" ? (
363	              // The same control, the same words and the same refusals as the
364	              // one on a stored map's six-button panel. What differs is only
365	              // what happens next: a generated map has no branch panel on this
366	              // screen yet, so the claim is drafted, checked and said, and
367	              // putting it on a branch of this map is the next piece of work.
368	              // No branch is sent because there is none to send.
369	              //
370	              // **It waits for the map to have a name of its own**, which is the
371	              // engine's `base_id` arriving with the likelihoods. A run that
372	              // broke or whose stream was dropped never gets one, and offering
373	              // to add a claim to a map that has no identifier would send the
374	              // *run's* name to a route that asks for the map's.
375	              <AddAClaim
376	                baseId={growth.world.baseId}
377	                andThen="It is checked against this map and ready to go onto a branch of it."
378	              />
379	            ) : null}
380	
381	            <Inspector
382	              world={growth.world}
383	              selection={selection}
384	              generation={{
385	                seed: growth.seed,
386	                promptFingerprint: growth.receipt?.prompt_hash ?? null,
387	                working,
388	                unknown: growth.unknown,
389	                openAt,
390	              }}
391	            />
392	          </>
393	        )
394	      }
395	      origin={
396	        <>
397	          <p className="map-origin__line">{growth.world.origin}</p>
398	          {replaying ? (
399	            <p className="map-origin__line">
400	              {replaySentence({
401	                recordingDate: growth.receipt?.recording_date ?? null,
402	                receiptMode: growth.receipt?.mode ?? null,
403	              })}
404	            </p>
405	          ) : null}
406	          <DoneLine
407	            done={growth.done}
408	            failure={growth.failure}
409	            endedEarly={phase === "ended_early"}
410	            // The offer is made only where there is something to offer: a stream
411	            // that stopped without saying why. A run that finished has its map on
412	            // screen, and a button asking whether to spend it all again would be
413	            // a control looking for a reason to exist.
414	            runAgain={
415	              phase === "ended_early" ? { costsMoney: !replaying, go: onRunAgain } : undefined
416	            }
417	          />
418	          {(growth.world.warnings ?? []).map((warning) => (
419	            <p className="map-origin__line" key={warning}>
420	              {warning}
421	            </p>
422	          ))}
423	        </>
424	      }
425	    />
426	  );
427	}
